Funcion pair <- JsonPair(name Como Cadena, stock Como Entero)
  Definir pair Como Cadena;
  pair <- '"' + name + '": ' + ATexto(stock);
FinFuncion

Algoritmo TwoPairs
  Definir firstName Como Cadena;
  Definir firstStock Como Entero;
  Definir secondName Como Cadena;
  Definir secondStock Como Entero;
  Leer firstName;
  Leer firstStock;
  Leer secondName;
  Leer secondStock;
  Escribir "{", JsonPair(firstName, firstStock), ", ", JsonPair(secondName, secondStock), "}";
FinAlgoritmo
